upstream flask_backend {
    # Option 1: TCP socket (default)
    server 127.0.0.1:8000;

    # Option 2: Unix socket (uncomment and comment Option 1 for better performance)
    # server unix:/run/gunicorn/gunicorn.sock fail_timeout=0;

    keepalive 16;
}

# Rate limiting zone
limit_req_zone $binary_remote_addr zone=flask_limit:10m rate=30r/s;

server {
    listen 80;
    server_name _;

    # Security headers
    add_header X-Frame-Options "SAMEORIGIN" always;
    add_header X-Content-Type-Options "nosniff" always;
    add_header X-XSS-Protection "1; mode=block" always;
    add_header Referrer-Policy "strict-origin-when-cross-origin" always;

    # Gzip compression
    gzip on;
    gzip_types application/json text/plain text/css application/javascript text/xml application/xml;
    gzip_min_length 256;
    gzip_vary on;

    # Timeouts — Flask/Gunicorn can be slower than Go
    proxy_connect_timeout 30s;
    proxy_send_timeout    60s;
    proxy_read_timeout    60s;
    send_timeout          60s;

    # Request size limit (for file uploads etc.)
    client_max_body_size 16M;

    # Main application
    location / {
        proxy_pass http://flask_backend;
        limit_req zone=flask_limit burst=50 nodelay;

        # Standard proxy headers
        proxy_set_header Host              $host;
        proxy_set_header X-Real-IP         $remote_addr;
        proxy_set_header X-Forwarded-For   $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header X-Forwarded-Host  $host;
        proxy_set_header X-Forwarded-Port  $server_port;
        proxy_set_header Connection        "";
        proxy_http_version 1.1;

        # Redirect server error pages to static error page
        proxy_intercept_errors on;
    }

    # Health check endpoint (bypass rate limiting)
    location = /health {
        proxy_pass http://flask_backend;
        proxy_set_header Host $host;
        proxy_http_version 1.1;
        proxy_set_header Connection "";
        access_log off;
        limit_req off;
    }

    # Static files — serve directly by Nginx for performance
    location /static/ {
        alias /data/agent/choucisan/static/;
        expires 30d;
        add_header Cache-Control "public, immutable";
        access_log off;
    }

    # Favicon
    location = /favicon.ico {
        alias /data/agent/choucisan/static/favicon.ico;
        access_log off;
        log_not_found off;
    }

    # Deny access to hidden files and Python artifacts
    location ~ /\. {
        deny all;
        access_log off;
        log_not_found off;
    }

    location ~ __pycache__ {
        deny all;
        access_log off;
        log_not_found off;
    }

    # Custom error pages
    error_page 502 503 504 /50x.html;
    location = /50x.html {
        root /usr/share/nginx/html;
        internal;
    }
}
